    assert.strictEqual(style.getPropertyValue("flex-grow"), "0");
    assert.strictEqual(style.getPropertyValue("flex-shrink"), "1");
    assert.strictEqual(style.getPropertyValue("flex-basis"), "250px");
    style.removeProperty("flex");
