  });

  it("supports var with var fallback", () => {
    const style = new CSSStyleDeclaration(globalObject);
    style.setProperty("width", "var(--foo, var(--bar))");
    assert.strictEqual(style.getPropertyValue("width"), "var(--foo, var(--bar))");
