      const partValues = ["1px", "2px", "3px", "4px"];

      for (let j = 0; j < parts.length; j++) {
        const partToRemove = parts[j];
        style[property] = partValues.join(" ");
        style[property + partToRemove] = "";

        // Main property should have been removed
