      for (const prop of props) {
        style[prop] = "10px";
        assert.strictEqual(style[prop], "10px");
        style[prop] = undefined;
        assert.strictEqual(style[prop], "10px");
      }
    }

    testParts("margin");
    testParts("padding");
  });

  it("setting null to background works", () => {
