      onChangeCallback: () => {
        called++;
      }
    });
    style.removeProperty("opacity");
    assert.strictEqual(called, 0);
  });

  it("setting float should work the same as cssfloat", () => {
    const style = new CSSStyleDeclaration(globalObject);
    style.float = "left";
